# עדכון הנתונים לפי לוח הפרמטרים האמיתי (עמוד 16 במדריך)
import pathlib, re
p = pathlib.Path(__file__).parent.parent / 'src/data.js'
s = p.read_text(encoding='utf-8')

def setnode(id_, new):
    global s
    m = re.search(r"node\('" + re.escape(id_) + r"', \{.*?\}\);\n", s, re.S)
    assert m, id_
    s = s[:m.start()] + new.strip('\n') + '\n' + s[m.end():]

def rep(a, b):
    global s
    assert a in s, 'MISSING ' + a[:80]
    s = s.replace(a, b, 1)

setnode('p_aspect', r"""node('p_aspect', { en: 'Aspect Ratio', he: 'יחס תמונה', icon: 'aspect', type: 'list', where: 'אריח אמצעי', o: O(['Auto', 'אוטומטי (לפי כיוון המצלמה)'], ['Custom', 'מותאם (4K ריבועי 3840×3840)']), def: 'Auto',
  d: 'ברירת המחדל Auto: כשהמצלמה לרוחב מקבלים 16:9 או 4:3, וכשהיא לאורך 9:16. Custom מצלם 4K ריבועי מלא כדי לחתוך אחר כך לרוחב או לאורך (ליוטיוב ולסטוריז).' });""")
setnode('p_res', r"""node('p_res', { en: 'Resolution', he: 'רזולוציה', icon: 'res', type: 'list', o: O(['1080p/16:9', '1080p ‏16:9'], ['2.7K/16:9', '2.7K ‏16:9'], ['2.7K/4:3', '2.7K ‏4:3'], ['4K/16:9', '4K ‏16:9'], ['4K/4:3', '4K ‏4:3'], ['8K/16:9', '8K ‏16:9'], ['4K/1:1', '4K ריבועי (Custom)']), def: '4K/16:9',
  d: 'הגלגל העליון בלוח הפרמטרים: רזולוציה ויחס תמונה יחד. 8K ‏(7680×4320) רק ב-16:9 ועד 30fps, עם ייצוב RockSteady/RockSteady+ בלבד, שדה ראייה רגיל/רחב טבעי/רחב, בלי גוון קולנועי ועדיפות לאיכות, ו-ISO עד 12800. כשהמצלמה לאורך מופיעים 9:16.' });""")
rep("node('p_fps', { en: 'Frame Rate', he: 'קצב פריימים', icon: 'fps', type: 'list',", "node('p_fps', { en: 'Frame Rate', he: 'קצב פריימים', icon: 'fps', type: 'list', wheel: 1,")
# קבוצות האריחים העליונים
rep("/* פרמטרים (החלקה למעלה) */", """/* פרמטרים (החלקה למעלה) */
node('p_recmode', { en: 'Pre-Rec / Loop Recording', he: 'הקלטה מוקדמת / במעגל', icon: 'video', type: 'page', where: 'אריח שמאלי', kids: ['p_prerec', 'p_loop'], d: 'האריח השמאלי בלוח הפרמטרים (וידאו ולילה). אפשר להפעיל רק אחת מהן בכל פעם.' });
node('p_eisfov', { en: 'EIS | FOV', he: 'ייצוב | שדה ראייה', icon: 'eis', type: 'page', where: 'אריח ימני (RS | Wide)', kids: ['p_eis', 'p_fov'], d: 'האריח הימני בלוח הפרמטרים. מציג בקיצור את הייצוב ושדה הראייה.' });
node('p_neisfov', { en: 'EIS | FOV', he: 'ייצוב | שדה ראייה', icon: 'eis', type: 'page', where: 'אריח ימני', kids: ['p_neis', 'p_nfov'], d: 'במצב לילה: RockSteady/RockSteady+ ושלושה שדות ראייה.' });""")
rep("kids: ['p_prerec', 'p_loop', 'p_eis', 'p_fov', 'p_aspect', 'p_res', 'p_fps'] });", "kids: ['p_recmode', 'p_aspect', 'p_eisfov', 'p_res', 'p_fps'] });")
rep("kids: ['p_prerec', 'p_loop', 'p_neis', 'p_nfov', 'p_nres', 'p_nfps'] });", "kids: ['p_recmode', 'p_neisfov', 'p_nres', 'p_nfps'] });")
rep("kids: ['p_aspect', 'p_res', 'p_fps'] });", "kids: ['p_aspect', 'p_eisfov', 'p_res', 'p_fps'] });")
# where של הפרמטרים הישנים (עכשיו בתוך הדפים)
for k in ['p_prerec', 'p_loop', 'p_eis', 'p_fov']:
    s = re.sub(r"(node\('" + k + r"', \{[^\n]*?), where: '[^']*'", r"\1", s)
s = s.replace("where: 'פינה ימנית עליונה (RS | Wide)',", "").replace("where: 'פינה ימנית עליונה',", "").replace("where: 'פינה שמאלית עליונה',", "")
# תיאורי מסך הצילום לפי האיור בעמוד 15
rep("d: 'כמה זמן הקלטה (או כמה תמונות) נשאר בכרטיס או בזיכרון הפנימי (50GB זמינים).' });", "d: 'פינה שמאלית עליונה (מספר 1 באיור): כמה זמן הקלטה נשאר, למשל 1h53m. האייקון מראה אם שומרים לזיכרון הפנימי או לכרטיס.' });")
rep("d: 'אחוז הסוללה של המצלמה.' });", "d: 'פינה ימנית עליונה (מספר 4): אחוז הסוללה, כתוב בתוך סמל הסוללה.' });")
rep("d: 'התמונה הממוזערת בפינה: התמונה או הסרטון האחרונים. הקשה פותחת את הגלריה.' });", "d: 'שמאל, באמצע (מספר 2): ריבוע עם משולש. הקשה מציגה את התמונה או הסרטון האחרונים.' });")
rep("d: 'המצב הנוכחי. הקשה (או החלקה לצד) פותחת את בורר המצבים.' });", "d: 'פינה שמאלית תחתונה (מספר 3): אייקון המצב הנוכחי. הקשה (או החלקה לצד) פותחת את בורר המצבים.' });")
rep("d: 'פותח את לוח התמונה והשמע: חשיפה, צמצם, צבע, גוון קולנועי ושמע. במצב PRO גם תריס, ISO ואיזון לבן.' });", "d: 'ימין, באמצע (מספר 5): שני קווים עם נקודות. פותח את לוח התמונה והשמע: חשיפה, צמצם, צבע, גוון קולנועי ושמע. במצב PRO גם תריס, ISO ואיזון לבן.' });")
rep("d: 'הצמצם הנוכחי (f/2.0 עד f/4.0). הקשה פותחת את מצבי הצמצם המשתנה.' });", "d: 'ימין, מתחת לאייקון הפרמטרים (מספר 6): למשל F2.8. הקשה פותחת את מצבי הצמצם המשתנה.' });")
rep("d: 'רזולוציה, קצב פריימים, ייצוב ושדה ראייה. הקשה (או החלקה למעלה) פותחת את הפרמטרים.' });", "d: 'למטה במרכז (מספר 7): למשל 4K30/RS/W = רזולוציה וקצב, ייצוב, שדה ראייה. הקשה (או החלקה למעלה) פותחת את הפרמטרים.' });")
rep("node('lv_zoom', { en: 'Zoom', he: 'זום', icon: 'zoom',", "node('lv_zoom', { en: 'Zoom', he: 'זום', icon: 'zoom1x',")
rep("d: 'זום דיגיטלי עד 2x.", "d: 'פינה ימנית תחתונה (מספר 8): 1x במסגרת. הקשה מחליפה זום. זום דיגיטלי עד 2x.")
p.write_text(s, encoding='utf-8')
print('ok')
